  FT["PH-H4146"] = {"id":"PH-H4146","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5344_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为三描礼士省增设2个Assistant 省立 Fiscal职位，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal in the Province of Zambales, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal in the Province of Zambales, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5344","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5344_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4146-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Zambales, is further amended to read as follows:\n\"Zambales, four assistant provincial fiscals;\""}},{"id":"PH-H4146-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal in the Province of Zambales, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4147"] = {"id":"PH-H4147","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5345_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第3860号共和国法的法案","en":"An Act Amending Republic Act Numbered Three Thousand Eight Hundred Sixty","orig":"An Act Amending Republic Act Numbered Three Thousand Eight Hundred Sixty"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5345","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5345_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4147-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one and two of Republic Act Numbered Three thousand eight hundred sixty are hereby amended to read as follows:\n\"Sec. 1. There shall be established, under the supervision and administration of the Director of Vocational Education, a school of fisheries in any suitable place within the Municipality of Santo Tomas, Province of La Union, to be known as the Santo Tomas School of Fisheries. The Director of Vocational Education shall promulgate, subject to the approval of the Secretary of Education, such rules and regulations to carry out the purpose of this Act. Said Director shall also acquire the necessary site for the school which shall not be less than eight hectares.\n\"Sec. 2. The sum of two hundred thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school for the fiscal year nineteen hundred sixty-nine. In subsequent years, the yearly General Appropriations Act shall provide for its operation and maintenance."}},{"id":"PH-H4147-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered Three Thousand Eight Hundred Sixty","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4148"] = {"id":"PH-H4148","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5346_1968.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Lingayen 湾开发公司在邦阿西楠省 Sual 市镇安装、运营和维护制冰厂与冷藏库并在该省第一选区各市镇及第二选区 Binmaley 市镇销售和分销冰的特许权法案","en":"An Act Granting the Lingayen Gulf Development Corporation a Franchise to Install, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Sual, Province of Pangasinan, and to Sell and Distribute Ice in the Municipalities Comprising the First Congressional District of Said Province and in the Municipality of Binmaley, of the Second Congressional District, Same Province","orig":"An Act Granting the Lingayen Gulf Development Corporation a Franchise to Install, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Sual, Province of Pangasinan, and to Sell and Distribute Ice in the Municipalities Comprising the First Congressional District of Said Province and in the Municipality of Binmaley, of the Second Congressional District, Same Province"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5346","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5346_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4148-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is hereby granted the Lingayen Gulf Development Corporation, hereinafter referred to as the grantee, a franchise to install, operate and maintain an ice plant and cold storage in the Municipality of Sual, Province of Pangasinan, for the purpose of manufacturing and distributing ice and supplying cold storage in the municipality comprising the first congressional district of said province, and in the Municipality of Binmaley, of the second congressional district, same province, and to charge and collect payments therefor according to a schedule of prices and rates which shall, at all times, be subject to regulation by the Public Service Commission or its legal successors."}},{"id":"PH-H4148-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice with a minimum daily capacity of five tons."}},{"id":"PH-H4148-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern safe and first class in every respect, and the grantee shall change or alter any of such apparatus and appurtenances at its expense whenever the Public Service Commission determines that public interest reasonably requires it."}},{"id":"PH-H4148-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date said plant shall operate and/or shall commence the manufacture and distribution of ice in the Municipality of Sual, Province of Pangasinan, subject to the express condition that the same shall be null and void unless the construction of said plant be begun within two years from the approval of this Act, except when prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by military power or any other cause beyond the grantee's control."}},{"id":"PH-H4148-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, only with respect to the fixing of rates and with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H4148-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, with the approval of the Congress of the Philippines may sell, grant, convey, assign, give in usufruct, or transfer this franchise and all property and rights acquired thereunder to any qualified individual, association or corporation competent to operate the business hereby authorized."}},{"id":"PH-H4148-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing individual, association of persons or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons or corporation."}},{"id":"PH-H4148-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Lingayen Gulf Development Corporation a Franchise to Install, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Sual, Province of Pangasinan, and to Sell and Distribute Ice in the Municipalities Comprising the First Congressional District of Said Province and in the Municipality of Binmaley, of the Second Congressional District, Same Province","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4149"] = {"id":"PH-H4149","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5347_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Jagna市","en":"An Act Converting Certain Sitios in the Municipality of Jagna, Province of Bohol, into Barrios","orig":"An Act Converting Certain Sitios in the Municipality of Jagna, Province of Bohol, into Barrios"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5347","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5347_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4149-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Jagna, Province of Bohol, are hereby converted into barrios to wit:\n(a) The sitio of Buyog is hereby converted into a barrio which shall be known as Barrio Buyog;\n(b) The sitio of Can-ipol is hereby converted into a barrio which shall be known as Barrio Can-ipol."}},{"id":"PH-H4149-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4150"] = {"id":"PH-H4150","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5348_1968.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Monark International，Inc. 在菲律宾境内建设、设立、维护和运营私人固定点对点、海岸、陆基、航空与陆上移动无线电台的临时许可的法案","en":"An Act Granting Monark International, Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Monark International, Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5348","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5348_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4150-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Monark International, Inc. a temporary permit to construct, establish, maintain and operate in the Philippines, at such places as the grantee may select subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point, coastal, land-based, aeronautical and land-mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each to be provided a radio transmitting and a radio receiving apparatus."}},{"id":"PH-H4150-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said radio stations or any of them on land of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H4150-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee and is granted upon the excess condition that same shall be void unless the construction of at least one of the said stations be begun within one year from the date approval of this Act and be completed within two years from said date."}},{"id":"PH-H4150-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate said radio stations at such places within the Philippines as the interest of the grantee and of its trade and business may justify."}},{"id":"PH-H4150-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder, but the grantee may use the international distress frequency of five to eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H4150-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H4150-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents of injuries, whether to property or persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H4150-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, or the rights or privileges acquired thereunder to any person, natural or juridical, nor merge with any other person, without the prior approval of the Congress of the Philippines. Any person, natural or juridical, to which this temporary permit may be sold, transferred or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person to which this temporary permit is sold, transferred or assigned, shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to such person."}},{"id":"PH-H4150-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H4150-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This temporary permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H4150-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Monark International, Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4151"] = {"id":"PH-H4151","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5349_1968.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Bislig Bay Lumber Company 在菲律宾境内建设、运营和维护私人固定、航空、陆基、船舶、无线电测定与无线电信标站的临时许可的法案","en":"An Act Granting Bislig Bay Lumber Company a Temporary Permit to Construct, Operate and Maintain Private Fixed, Aeronautical Fixed, Aeronautical, Land-Mobile/Portable, Based, Land-Mobile/Portable, Coast, Ship, Survival Craft, Radio Determination and Radio Beacon Stations for the Reception and Transmission of Wireless Intelligence in the Philippines","orig":"An Act Granting Bislig Bay Lumber Company a Temporary Permit to Construct, Operate and Maintain Private Fixed, Aeronautical Fixed, Aeronautical, Land-Mobile/Portable, Based, Land-Mobile/Portable, Coast, Ship, Survival Craft, Radio Determination and Radio Beacon Stations for the Reception and Transmission of Wireless Intelligence in the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5349","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5349_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4151-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Bislig Bay Lumber Company, its successors and assigns, a temporary permit to construct, maintain and operate in such places in the Philippines where it operates or transacts its business or renders its services, subject to the approval of the Secretary of Public Works and Communications, or any licensing authority, private fixed, aeronautical fixed, aeronautical, land mobile/portable, based, land mobile/portable, coast, ship, survival craft, radio determination and radio beacon stations for the reception and/or transmission of wireless intelligence on radiotelegraphy or radiotelephony, inclusive of but not limited to facsimile, radioteletype, nationally and/or internationally, each station to be provided with radio transmitting equipment and/or radio receiving equipment, as necessary."}},{"id":"PH-H4151-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the grantee, its successors or assigns, conducts its business or services at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of at least two radio stations be begun within two years from the date of the approval of this Act."}},{"id":"PH-H4151-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic public telecommunications business in the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee, its successors or assigns, the right to construct, install, maintain and operate its radio stations herein granted at the places above-mentioned for the primary purpose of promoting and protecting the business and other interest of the grantee."}},{"id":"PH-H4151-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall be engaged in communications regarding the grantee's business interests: Provided, However, That the grantee may allow affiliate, allied or associated companies to use any of its facilities on a non-profit basis."}},{"id":"PH-H4151-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its radio stations herein granted in the very low frequency, low frequency, medium frequency, high frequency, very high frequency, ultra high frequency, super high frequency and extreme high frequency that shall be assigned to it by the Secretary of Public Works and Communications, or by any licensing authority."}},{"id":"PH-H4151-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and private coastal radio stations or any of them on lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H4151-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio station maintained and operated in the Philippines."}},{"id":"PH-H4151-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H4151-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines."}},{"id":"PH-H4151-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use or possession thereof by any department of the Government upon just compensation."}},{"id":"PH-H4151-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H4151-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"In the event of any individual, partnership or corporation receiving from the Congress a similar permit in which there shall be any term or terms more favorable than those herein granted, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said individual, partnership or corporation."}},{"id":"PH-H4151-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Bislig Bay Lumber Company a Temporary Permit to Construct, Operate and Maintain Private Fixed, Aeronautical Fixed, Aeronautical, Land-Mobile/Portable, Based, Land-Mobile/Portable, Coast, Ship, Survival Craft, Radio Determination and Radio Beacon Stations for the Reception and Transmission of Wireless Intelligence in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4152"] = {"id":"PH-H4152","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5350_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在八打雁省设立北部工程区的法案","en":"An Act Creating the Northern Engineering District in the Province of Batangas","orig":"An Act Creating the Northern Engineering District in the Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5350","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5350_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4152-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the Third Congressional District of the Province of Batangas, except the City of Lipa, is hereby constituted into a separate engineering district to be known as the Northern Engineering District of the Province of Batangas, with principal offices at the Municipality of Tanauan, same province."}},{"id":"PH-H4152-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Communications shall allocate the necessary personnel, property, equipment, materials and supplies to the new engineering district within the period of ninety days after the approval of this Act."}},{"id":"PH-H4152-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Northern Engineering District in the Province of Batangas","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4153"] = {"id":"PH-H4153","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5351_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订并废止第513号共和国法（经第982号共和国法修正）若干条款的法案","en":"An Act Amending and Repealing Certain Sections of Republic Act Numbered Five Hundred Thirteen, as Amended by Republic Act Numbered Nine Hundred Eighty-Two","orig":"An Act Amending and Repealing Certain Sections of Republic Act Numbered Five Hundred Thirteen, as Amended by Republic Act Numbered Nine Hundred Eighty-Two"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5351","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5351_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4153-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one and fifteen of Republic Act Numbered Five hundred thirteen, as amended by Republic Act Numbered Nine hundred eighty-two, are further amended to read as follows:\n\"Sec. 1. There is hereby granted to the Republic Broadcasting System, hereinafter referred to as the \"grantee,\" a franchise for a period of twenty-five years from the approval of this Act to construct, maintain and operate commercially in the Philippines, at such places as the said grantee may select, subject to approval of the Secretary of Public Works and Communications, stations for radio and television broadcasting: Provided, That the holder of the franchise herein granted shall start the operation of at least one radio broadcasting station or one television station within one and a half years from the approval of said franchise. Failure to comply with this requirement shall ipso facto cancel and void the franchise.\n\"Sec. 15. The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines, first had. Any corporation to which this franchise may be sold, transferred, or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall be subject to all the conditions, terms, restrictions and limitations of this franchise, as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H4153-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Sections thirteen and fourteen of the same Act, as amended, are hereby repealed."}},{"id":"PH-H4153-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The title of the same Act is hereby amended to read as follows:\n\"An Act granting the Republic Broadcasting System a franchise to construct, maintain and operate stations for television and radio broadcasting in the Philippines and radio stations for international and domestic telecommunications."}},{"id":"PH-H4153-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending and Repealing Certain Sections of Republic Act Numbered Five Hundred Thirteen, as Amended by Republic Act Numbered Nine Hundred Eighty-Two","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4154"] = {"id":"PH-H4154","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5352_1968.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Examiner，Incorporated 在莱特与萨马省建设、安装、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting Examiner, Incorporated a Franchise to Construct, Install, Maintain and Operate Radio Broadcasting and Television Stations in the Provinces of Leyte and Samar","orig":"An Act Granting Examiner, Incorporated a Franchise to Construct, Install, Maintain and Operate Radio Broadcasting and Television Stations in the Provinces of Leyte and Samar"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 5352","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5352_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4154-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and the provisions of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments and other applicable laws, there is granted Examiner, Incorporated, its successors or assigns, and hereunder referred to as the \"grantee\" the right and privilege of constructing, installing, establishing and operating in the Provinces of Leyte and Samar, for commercial purposes and in the public interest, at those places as Examiner, Incorporated, may select and the Secretary of Public Works and Communications may approve, radio broadcasting and television stations in Leyte and Samar: Provided, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting and television stations, to reach the people on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use such stations for the broadcasting of obscene or indecent language or speech, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H4154-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace and order, to take over and operate thereof, or by any department of the Government without compensating the grantee for the said stations during the period when they shall be so operated."}},{"id":"PH-H4154-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In the event of any competing individual, partnership, or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership, or corporation."}},{"id":"PH-H4154-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H4154-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after six years from the date of approval of this Act, grantee shall have fulfilled such conditions, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H4154-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall not sell, convey, or otherwise transfer to any person, corporation, association or partnership this franchise without previous approval of the Congress."}},{"id":"PH-H4154-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H4154-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The President of the Philippines shall have the power of authority to permit the construction of said stations or any of them on any land of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H4154-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The stations of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee's services."}},{"id":"PH-H4154-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H4154-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use, or occupation of any land except such as is required for the actual necessary purposes for which this franchise is granted."}},{"id":"PH-H4154-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H4154-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"(a) This franchise shall not take effect nor shall any power thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths and channels to be used thereunder and determined the stations to and from which frequency and wave length may be used, and issued to the grantee a license for such use. (b) The Secretary of Public Works and Communications in allotting to the grantee the frequencies and wave lengths and channels referred to above, shall give due regard to the government's program of expanding its radio telecommunications, and on reasonable notice to the grantee may at any time change, cancel, or modify in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such action:\n(1) Whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications or stifle competition, or to obtain a monopoly in electrical communications or to secure unreasonable rates for such communications, or to violate otherwise the laws or public policy of the Philippine Republic;\n(2) Whenever in his judgment the public interests of the Republic of the Philippines require that such frequencies or wave lengths should be used for other purposes than those of the grantee, either by the Government of the Philippines or by other individuals or corporations licensed by it; and\n(3) Whenever in his judgment, for any reason, the public interest of the Philippines so require."}},{"id":"PH-H4154-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This franchise shall not be interpreted as to mean and exclusive grant of the privileges herein provided for."}},{"id":"PH-H4154-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the first of any of said stations shall be placed in operation, and is granted upon the express condition that same shall be void unless the construction of one station be begun within two years from the date of the approval of this Act and be completed within six years from said date."}},{"id":"PH-H4154-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Examiner, Incorporated a Franchise to Construct, Install, Maintain and Operate Radio Broadcasting and Television Stations in the Provinces of Leyte and Samar","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4155"] = {"id":"PH-H4155","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5354_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第296号共和国法（经修正）第68条第1款，将八打雁省八打雁市镇法官人数由1名增至2名的法案","en":"An Act Amending the First Paragraph of Section Sixty-Eight of Republic Act Numbered Two Hundred Ninety-Six, as Amended, by Increasing the Number of Municipal Judges of the Municipality of Batangas, Province of Batangas, from One to Two","orig":"An Act Amending the First Paragraph of Section Sixty-Eight of Republic Act Numbered Two Hundred Ninety-Six, as Amended, by Increasing the Number of Municipal Judges of the Municipality of Batangas, Province of Batangas, from One to Two"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5354","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5354_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4155-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of Section sixty-eight of Republic Act Numbered Two hundred ninety-six, as amended, is further amended to read as follows:\n\"Sec. 68. Appointment and distribution of municipal judges.— There shall be one municipal judge and one auxiliary municipal judge in each municipality and municipal district, and if the public interest shall so require, in any minor political division or unorganized territory in the Philippines, and such judges of municipal courts in each chartered city as their respective charters provide: Provided, That there shall be two municipal judges in the Municipality of Batangas, Province of Batangas: Provided, further, That in addition to the present number of municipal judges in the City of Manila and Quezon City as provided for in their respective charters, there shall be two additional municipal judges for the City of Manila and one additional municipal judge for Quezon City, who shall have jurisdiction, assignment and compensation provided for in the charter of their respective cities."}},{"id":"PH-H4155-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of twenty thousand pesos, or so much thereof as may be necessary, is appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act."}},{"id":"PH-H4155-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending the First Paragraph of Section Sixty-Eight of Republic Act Numbered Two Hundred Ninety-Six, as Amended, by Increasing the Number of Municipal Judges of the Municipality of Batangas, Province of Batangas, from One to Two","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4156"] = {"id":"PH-H4156","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5355_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权为北伊罗戈省Batac市镇Batac综合医院的维护与运营拨款20万比索的法案","en":"An Act Authorizing the Appropriation of Two Hundred Thousand Pesos for the Maintenance and Operation of the Batac General Hospital in the Municipality of Batac, Province of Ilocos Norte","orig":"An Act Authorizing the Appropriation of Two Hundred Thousand Pesos for the Maintenance and Operation of the Batac General Hospital in the Municipality of Batac, Province of Ilocos Norte"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5355","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5355_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4156-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the Batac General Hospital in the Municipality of Batac, Province of Ilocos Norte, during the fiscal year nineteen hundred sixty-nine. Thereafter, such sum as may be necessary for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4156-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Appropriation of Two Hundred Thousand Pesos for the Maintenance and Operation of the Batac General Hospital in the Municipality of Batac, Province of Ilocos Norte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4157"] = {"id":"PH-H4157","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5356_1968.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Asiatic Integrated 公司在 Mariveles 港建设、运营和维护私人码头与泊位的特许经营权法案","en":"An Act Granting a Franchise to the Asiatic Integrated Corporation to Construct, Operate and Maintain Private Piers and Wharves in the Port of Mariveles","orig":"An Act Granting a Franchise to the Asiatic Integrated Corporation to Construct, Operate and Maintain Private Piers and Wharves in the Port of Mariveles"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5356","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5356_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4157-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and to the terms and conditions imposed under this Act, there is hereby granted to the Asiatic Integrated Corporation, its successors or assigns, a one hundred percent Filipino corporation organized under, and by virtue of, the Corporation Law, hereinafter referred to as the grantee, a franchise for a period of twenty-five years, to construct, operate and maintain, in the Port of Mariveles, Province of Bataan, private piers and wharves for the use of vessels engaged in foreign or coastwise trade. The plans, specifications and construction of any pier, wharf or wharves by the grantee hereunder shall be subject to the approval of the Department of Public Works and Communications."}},{"id":"PH-H4157-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Cargoes loaded and unloaded in the grantee's piers and wharves shall be properly inspected and/or examined in accordance with the Tariff and Customs Code of the Philippines by the Bureau of Customs which shall also collect thereon, if required, the corresponding customs duties, taxes, fees, wharfage dues and other charges provided in the same Code."}},{"id":"PH-H4157-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall be liable to pay the same taxes on its real property, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay."}},{"id":"PH-H4157-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise shall continue to be in force for the period provided for in Section one of this Act and during the time that the Government has not established similar service at the places selected by the grantee. It is likewise granted upon the express condition that the same shall be void unless the construction of at least one wharf or pier be begun within two years from the date of approval of this act and be completed within four years from said date, unless prevented by fortuitous cause or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other reasonable cause beyond the grantee's herein for the construction of grantee's pier or wharf shall be suspended."}},{"id":"PH-H4157-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The President of the Philippines, through the proper department of the Government, shall have the power and authority to permit the location and of said private piers or wharves of the grantee on any land or water within the jurisdiction of the Port of Mariveles upon such terms as he may prescribe."}},{"id":"PH-H4157-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall hold the national, provincial, city and municipal governments harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, arising out of the construction, operation and maintenance of its wharves."}},{"id":"PH-H4157-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise, or the rights or privileges acquired thereunder to any person, firm, company, corporation, or other commercial or legal entity, nor merge with any other person, firm, company or corporation organized for the same purpose, without the prior approval of Congress."}},{"id":"PH-H4157-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee's piers or wharves or to authorize the temporary use or possession thereof by any department, bureau, office, agency or instrumentality of the Government upon payment of just compensation."}},{"id":"PH-H4157-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"In the event of any competing individual, association, or corporation receiving from the Congress of the Philippines similar franchise in which there shall be terms tending to place the herein grantee at any disadvantage, then such terms shall ipso facto become part of the terms of the Act and shall operate in favor of the grantee as in the case of said competing individual, association, or corporation."}},{"id":"PH-H4157-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This franchise is granted under the condition that it is non-exclusive and shall be subject to amendment, alteration or repeal by the Congress when the public interest so requires."}},{"id":"PH-H4157-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting a Franchise to the Asiatic Integrated Corporation to Construct, Operate and Maintain Private Piers and Wharves in the Port of Mariveles","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4158"] = {"id":"PH-H4158","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5357_1968.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"授予 Pacifico C. Marana 在八打雁省 Taal 市镇建设、运营制冰厂与冷藏库并在该市镇及该省各市镇销售冰和供应冷藏的特许权法案","en":"An Act Granting Pacifico C. Marana a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Taal, Province of Batangas, and to Sell Ice and Supply Cold Storage Within the Municipality and the Municipalities of Lemery, San Nicolas, Agoncillo, Sta. Teresita, San Luis, Calaca, Balayan, Mabini, Batangas, Tuy and Nasugbu, All in the Province of Batangas","orig":"An Act Granting Pacifico C. Marana a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Taal, Province of Batangas, and to Sell Ice and Supply Cold Storage Within the Municipality and the Municipalities of Lemery, San Nicolas, Agoncillo, Sta. Teresita, San Luis, Calaca, Balayan, Mabini, Batangas, Tuy and Nasugbu, All in the Province of Batangas"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5357","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5357_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4158-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is hereby granted to Pacifico C. Marana, hereinafter referred to as the grantee, a franchise to construct, operate and maintain a hundred-ton maximum capacity ice plant and cold storage in the said municipality of Taal, Province of Batangas, for the purpose of manufacturing and distributing ice and supplying cold storage in the said municipality and in the municipalities of Lemery, San Nicolas, Sta. Teresita, San Luis, Calaca, Balayan, Mabini, Agoncillo, Batangas, Tuy and Nasugbu, all in the Province of Batangas, and to charge and collect a schedule of prices and rates for the ice and cold storage so furnished which schedule of prices and rates shall at all times be subject to regulation by the Public Service Commission."}},{"id":"PH-H4158-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date said plant is placed in operation and/or commences the manufacture and distribution of ice in the municipalities of Taal, Lemery, Sta. Teresita, San Luis, San Nicolas, Agoncillo, Mabini, Calaca, Balayan, Tuy and Nasugbu, all in the Province of Batangas, subject to the express condition that this franchise shall be null and void unless the construction of said plant is begun within two years from the date of the approval of this Act and completed within four years from said date, except when prevented by an act of God, martial law, riot, civil commotion, usurpation by military power or any other acts of force majeure."}},{"id":"PH-H4158-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and, whenever the Public Service Commission shall determine that public interest reasonably requires it, the grantee shall change or alter any of the apparatus and appurtenances at his expense."}},{"id":"PH-H4158-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The books, records, and accounts of the grantee shall, always be open to inspection by the municipal treasurer or his authorized representatives, and it shall be the duty of the grantee to submit to the municipal treasurer quarterly reports in duplicate, showing the gross receipts for the past quarter, one of which shall be forwarded by the municipal treasurer to the Auditor General, who shall keep the same on file."}},{"id":"PH-H4158-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, only with respect to the fixing of rates. In consideration of the franchise hereby granted, the grantee shall pay quarterly into the municipal treasury a tax equivalent of two per centum of the gross earnings derived by the grantee from his operation under this franchise."}},{"id":"PH-H4158-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In event of any competing individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, the such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said individual, association of persons or corporation."}},{"id":"PH-H4158-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Pacifico C. Marana a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Taal, Province of Batangas, and to Sell Ice and Supply Cold Storage Within the Municipality and the Municipalities of Lemery, San Nicolas, Agoncillo, Sta. Teresita, San Luis, Calaca, Balayan, Mabini, Batangas, Tuy and Nasugbu, All in the Province of Batangas","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4159"] = {"id":"PH-H4159","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5358_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为新比斯开省增设2个Assistant 省立 Fiscal职位，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal for the Province of Nueva Vizcaya, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal for the Province of Nueva Vizcaya, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5358","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5358_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4159-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Nueva Vizcaya, is further amended to read as follows:\n\"Nueva Vizcaya, five assistant provincial fiscals;\""}},{"id":"PH-H4159-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal for the Province of Nueva Vizcaya, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4160"] = {"id":"PH-H4160","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5359_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将Bicol电力公司的特许经营权再延长二十五年的法案","en":"An Act Extending the Franchises of the Bicol Electric Company, Inc. for Another Twenty-Five Years","orig":"An Act Extending the Franchises of the Bicol Electric Company, Inc. for Another Twenty-Five Years"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5359","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5359_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4160-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established under Act Numbered Twenty-six hundred and forty-seven, as amended by Act Numbered Twenty-eight hundred and eighty-two, the franchise granted to Mariano Abella Y Isaac, and assumed and taken by the Bicol Electric Company, to install, operate and maintain an electric light, heat and power system in the City of Naga; and of the franchises granted by resolutions of the municipal councils of Camaligan, Bombon and Calabanga in the Province of Camarines Sur; of the municipal councils of Ligao, Oas and Guinobatan in the Province of Albay; and of the municipal council of Gubat in the Province of Sorsogon, to the Manila Electric Company, assumed and taken over by the Bicol Electric Company, to install, operate and maintain an electric light, heat and power system in their respective municipalities, later revised and consolidated by Republic Act Numbered Nine hundred and thirty-four, are hereby extended for a period of twenty-five years from the date of their expiration."}},{"id":"PH-H4160-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Franchises of the Bicol Electric Company, Inc. for Another Twenty-Five Years","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4161"] = {"id":"PH-H4161","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5360_1968.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"授予 Panay 电力公司在伊洛伊洛市及伊洛伊洛省 Santa Barbara 与 Pavia 市镇经营电灯、热力与动力系统的特许权法案","en":"An Act Granting a Franchise for an Electric Light, Heat and Power System to Panay Electric Company, Inc. in the City of Iloilo, and in the Municipalities of Santa Barbara and Pavia, Both in the Province of Iloilo","orig":"An Act Granting a Franchise for an Electric Light, Heat and Power System to Panay Electric Company, Inc. in the City of Iloilo, and in the Municipalities of Santa Barbara and Pavia, Both in the Province of Iloilo"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5360","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5360_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4161-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and to the terms and conditions established in Act Numbered Thirty-six hundred thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, there is granted to Panay Electric Company, Inc. for a period of twenty-five years from the date of approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and/or distributing electric light, heat and/or power for sale within the City of Iloilo and the municipalities of Santa Barbara and Pavia, both in the Province of Iloilo. The grantee shall further have the right and privilege to install, lay and maintain on all streets, public thoroughfares, bridges and public places within said limits, poles, wires, transformers, capacitors, overhead protective devices, and pole line hardware, and other equipment necessary for the sale distribution of electric current to the public."}},{"id":"PH-H4161-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the National Power Corporation shall have established its line in the areas adjacent to or over the territory covered by this franchise, the National Power Corporation may make available its power and heat only after negotiations with and through or with the authority and consent of the grantee, which shall be the exclusive distributor of whatever power the aforenamed corporation may make available adjacent to or within the territory covered by this franchise."}},{"id":"PH-H4161-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The rates for the sale of electric light, heat and/or power shall be subject to the regulation by the Public Service Commission."}},{"id":"PH-H4161-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"It is expressly provided that in the event the Government should desire to operate and maintain for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the government all equipment therein at fair market value."}},{"id":"PH-H4161-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In consideration of the franchise and rights hereby granted, the grantee shall pay a franchise tax equal to two per centum of the gross earnings for electric current sold under this franchise: Provided, That the said franchise tax of two per centum of the gross earnings shall be in lieu of taxes, duties and assessments, licenses and fees of whatever nature and which may be levied by any governmental authority now and in the future upon privileges, earnings, income, machinery and equipment, watt-hour meters, poles, wires, transformers, and insulators used by the grantee, from which taxes, duties, licenses, fees and assessments the grantee is hereby expressly exempted."}},{"id":"PH-H4161-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Upon approval of this Act, Acts Numbered twenty-nine hundred and eighty-three and Thirty-six hundred and sixty-five are hereby repealed and this franchise shall be lieu thereof."}},{"id":"PH-H4161-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting a Franchise for an Electric Light, Heat and Power System to Panay Electric Company, Inc. in the City of Iloilo, and in the Municipalities of Santa Barbara and Pavia, Both in the Province of Iloilo","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4162"] = {"id":"PH-H4162","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5361_1968.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"修订第 1449 号共和国法（即授予 A. Soriano y Cia. 在菲律宾境内建设、维护和运营私人固定点对点、海岸、航空、陆基与陆上移动无线电台的临时许可的法案）","en":"An Act Amending Republic Act Numbered One Thousand Four Hundred Forty-Nine, Entitled \"An Act Granting A. Soriano y Cia., a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Aeronautical, Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Amending Republic Act Numbered One Thousand Four Hundred Forty-Nine, Entitled \"An Act Granting A. Soriano y Cia., a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Aeronautical, Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5361","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5361_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 条号自第 2 条起而非自 1 起（止于第 9 条）：本法为“修改型法条”，仅重述被修改的个别条文，条号承被修改法之后，属该体例使然。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4162-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one of the same Act is hereby amended to read as follows:\n\"Sec. 1. There is hereby granted to A. Soriano y Cia., successors or assigns, a temporary permit to construct, maintain and operate in such places in the Philippines where it operates or transacts its business or renders its services, subject to the approval of the Secretary of Public Works and Communications or any licensing authority, private fixed, aeronautical, aeronautical fixed, aircraft, land mobile/portable, based, land mobile/portable, coast, ship, survival craft, radio determination and radio beacon stations for the reception and/or transmission of wireless messages on radiotelegraphy or radiotelephony, inclusive of but not limited to facsimile, radioteletype, nationally and/or internationally, each station to be provided with radio transmitting equipment and/or radio receiving equipment, as necessary.\""}},{"id":"PH-H4162-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section two of the same Act is hereby amended to read as follows:\n\"Sec. 2. This temporary permit shall continue to be in force during the time that the grantee successors or assigns, conducts its business or services at the places selected by the grantee but in no case to go beyond July four, nineteen hundred seventy-four, and is granted upon the express condition that the same shall be void unless the construction, installation of at least two radio stations be begun within two years from the date of the approval of this Act.\""}},{"id":"PH-H4162-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section three of the same Act is hereby amended to read as follows:\n\"Sec. 3. The grantee, successors or assigns, shall not engage in domestic business of telecommunications in the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain and operate its radio stations herein granted at the places above-mentioned for the primary purpose of promoting and protecting the business and other interests of the grantee.\""}},{"id":"PH-H4162-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section four of the same Act is hereby amended to read as follows:\n\"Sec. 4. No fees shall be charged by the grantee as the radio station that may be established by virtue of this Act shall engage in communications regarding the grantee's business interests only.\""}},{"id":"PH-H4162-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section eight of the same Act is hereby amended to read as follows:\n\"Sec. 8. The grantee, successors or assigns, is authorized to operate its radio stations herein granted in the very low frequency, low frequency, medium frequency, high frequency, very high frequency, ultra high frequency, super high frequency, and extreme high frequency that may be assigned to it by the Secretary of Public Works and Communications, or by any licensing authority.\""}},{"id":"PH-H4162-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The same Act is further amended by adding after Section ten thereof the following new sections to read as follows:\n\"Sec. 11. The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and private coastal radio stations or any of them on lands of the public domain upon such terms as he may prescribe.\n\"Sec. 12. In the event of any individual, partnership or corporation receiving from the Congress a similar permit in which there shall be any term or terms more favorable than those herein granted, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said individual, partnership or corporation.\""}},{"id":"PH-H4162-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section eleven of the same Act is hereby redesignated as Section thirteen thereof."}},{"id":"PH-H4162-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered One Thousand Four Hundred Forty-Nine, Entitled \"An Act Granting A. Soriano y Cia., a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Aeronautical, Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4163"] = {"id":"PH-H4163","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5362_1968.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"授予 Bello M. Casanova 建设、维护和运营无线电广播站及国内电信无线电台的特许经营权法案","en":"An Act Granting Bello M. Casanova a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations and Radio Stations for Domestic Telecommunications","orig":"An Act Granting Bello M. Casanova a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations and Radio Stations for Domestic Telecommunications"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 5362","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5362_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4163-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and the provisions of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes,\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereinafter granted to Bello M. Casanova, his successors or assigns, and hereunder referred to as the \"grantee,\" the right and privilege of constructing, installing, establishing and operating from Davao City, Cagayan de Oro City, the Municipality of Malaybalay, Province of Bukidnon and/or at such other places within the Philippines, as Bello M. Casanova may select and the Secretary of Public Works and Communications may approve, radio broadcasting stations and radio stations for the reception and transmission of messages on radio stations in the domestic public fixed point-to-point and public base, aeronautical and land mobile stations, including coastal marine service with the corresponding relay stations for the reception and transmission of wireless messages on radiotelegraphy and/or radiotelephony, radioteletype, radiophoto, facsimile, music, pictures, advertisement and such other types of emission within the Philippines and with vessels at sea and aircrafts over the air, irrespective of whether such vessels and aircrafts are within or without the Philippines."}},{"id":"PH-H4163-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to take over and operate the said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H4163-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction of said stations or any of them on any land of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H4163-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the first of said stations shall be placed in operation and is granted upon the express condition that the same shall be void unless the construction of said station be begun within two years from the date of the approval of this Act and be completed within ten years from said date."}},{"id":"PH-H4163-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) This franchise shall not take effect nor shall any power thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder and determined the stations to and from which each frequency and wave length may be used, and issued to the grantee a license for such use. (b) The Secretary of Public Works and Communications, on reasonable notice to the grantee, may at any time change, or cancel, or modify, in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such action: (1) whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications, or stifle competition or to secure unreasonable rates for such communication, or to violate otherwise the laws or public policy of the Philippine Republic; (2) whenever in his judgment the public interests of the Republic of the Philippines requires that such frequencies or wave lengths should be used for other purposes than those of the grantee, either by the Government of the Philippines or by other individuals or corporations licensed by it; and (3) whenever in his judgment, for any reason, the public interests of the Philippines so require."}},{"id":"PH-H4163-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The stations of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee's services."}},{"id":"PH-H4163-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H4163-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use, or occupation of any land except such as is required for the actual necessary purposes for which this franchise is granted."}},{"id":"PH-H4163-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep an account of the gross receipts of its business and shall furnish the Auditor General and the Treasurer of the Philippines with a copy of such account not later than the thirty-first day of January of each year for the preceding year. All the books and accounts of the grantee pertaining to his business shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H4163-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions, and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said persons, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H4163-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee, his successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H4163-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after four years from the date of the approval of this Act, the grantee shall have fulfilled said conditions, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H4163-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the term hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H4163-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. (b) The grantee shall further pay to the Treasurer of the Philippines each year, within ten days after the audit and approval of the accounts as prescribed in this Act such tax as provided for under existing laws."}},{"id":"PH-H4163-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H4163-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H4163-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall contribute to the public welfare, shall assist in the function of public information and education, shall not use its station for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H4163-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Bello M. Casanova a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations and Radio Stations for Domestic Telecommunications","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4164"] = {"id":"PH-H4164","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5363_1968.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"将北民答那峨理工学院更名为 Iligan 理工学院并作为民答那峨国立大学组成部分的法案，并为其他目的","en":"An Act Changing the Name of the Northern Mindanao Institute of Technology to Iligan Institute of Technology, Integrating it as a Unit of the Mindanao State University, and for Other Purposes","orig":"An Act Changing the Name of the Northern Mindanao Institute of Technology to Iligan Institute of Technology, Integrating it as a Unit of the Mindanao State University, and for Other Purposes"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5363","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5363_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4164-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Northern Mindanao Institute of Technology shall hereafter be known as Iligan Institute of Technology and is hereby integrated as a unit of the Mindanao State University."}},{"id":"PH-H4164-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Iligan Institute of Technology shall provide a program for an effective manpower training urgently needed for the industrial and commercial development of the Mindanao State University."}},{"id":"PH-H4164-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby created an Advisory Council whose function it shall be to establish and promote close coordination between the training programs of the Institute and the manpower needs of industry, business and other sectors of the economy, particularly, those which will hasten the development of the Mindanao regions."}},{"id":"PH-H4164-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The composition of the Advisory Council, including the qualifications of members and their terms of office, shall be determined by the Board of Regents from time to time, so as to give representation to the varying, developing, expanding and emerging industry, trade and business, including the Mindanao State University: Provided, That the Mayor of the City of Iligan, a representative of the City Council of Iligan and the Director of Vocational Education or his representative shall be ex-officio members."}},{"id":"PH-H4164-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the formulation of policies and action on matters affecting the administration of the Iligan Institute of Technology, the Mayor of the City of Iligan, the Chairman of the Advisory Council and the President of the Iligan Chamber of Industries shall be considered ex officio members of the Board of Regents of the Mindanao State University and shall be entitled to all the rights and privileges of the members of the Board of Regents: Provided, However, That their participation shall not extend on other matters beyond the interest and concern of the Iligan Institute of Technology.\nThe Secretary of the Board of Regents shall issue notification to the said members of the Board whenever the agenda of the Board meeting includes items affecting the Iligan Institute of Technology."}},{"id":"PH-H4164-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"To carry out the purposes of this Act, the sum appropriated for the operation and maintenance of Lanao Technical School (Northern Mindanao Institute of Technology) in the annual General Appropriations Act for the fiscal year nineteen hundred and sixty-nine shall be transferred to the Iligan Institute of Technology and utilized for its operation and maintenance. The government of the City of Iligan shall allocate annually, beginning the fiscal year nineteen hundred and sixty-nine, as part of its regular budget a subsidy in a lump sum an amount equal to three per centum of its total gross income from all sources, for the support and maintenance of the Institute: Provided, That the sum appropriated for the Institute by the National Government, by the Mindanao State University and from other sources shall aggregate not less than twice the said subsidy allocated by the government of the City of Iligan. The said subsidy from the City of Iligan, together with the annual contribution of the National Government, incomes from the operation of the Institute, and other funds secured from the National Government shall be disbursed by the Board of Regents of the Mindanao State University in accordance with the purposes of this Act."}},{"id":"PH-H4164-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"As a unit of the Mindanao State University, the Iligan Institute of Technology shall be governed by Republic Act Numbered Thirteen hundred eighty-seven, as amended, otherwise known as the Charter of Mindanao State University, and its administration shall be vested in the Board of Regents of the said University, all provisions of law to the contrary notwithstanding. The Northern Mindanao Institute of Technology is hereby abolished and all its personnel, unexpended appropriations, properties and other assets, whether in its name or that of the Lanao Technical School, are hereby transferred to the Mindanao State University: Provided, That nothing in this Act shall be interpreted as to terminate the services of the said transferred personnel or demote them in rank and/or salary."}},{"id":"PH-H4164-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Beginning with the fiscal year nineteen hundred sixty-nine and every fiscal year thereafter, the sum of one million pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the support of the Iligan Institute of Technology. This amount shall be included in the annual General Appropriations Act as a separate item in the government contribution to the Mindanao State University, and disbursed by the Board of Regents of the said University in accordance with the purposes of this Act."}},{"id":"PH-H4164-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Northern Mindanao Institute of Technology to Iligan Institute of Technology, Integrating it as a Unit of the Mindanao State University, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4165"] = {"id":"PH-H4165","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5364_1968.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"授予 Dominador A. Simon 在哥打巴托市建设、维护和运营制冰厂与冷藏库并在该省与市销售冰和供应冷藏的特许权法案","en":"An Act Granting Dominador A. Simon a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the City of Cotabato and to Sell Ice and Supply Cold Storage Within the Province and City of Cotabato","orig":"An Act Granting Dominador A. Simon a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the City of Cotabato and to Sell Ice and Supply Cold Storage Within the Province and City of Cotabato"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5364","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5364_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4165-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions established in this Act, and the provisions of Commonwealth Act Numbered One hundred and forty-six, as amended, and of the Constitution, applicable thereto, there is hereby granted to Dominador A. Simon, hereinafter called the grantee, his successors or assigns, for a period of twenty-five years from the approval of this Act, the right and privilege to construct, operate and maintain ice plant and cold storage in the City of Cotabato, for the purpose of manufacturing and distributing ice within said city and province of Cotabato and to charge and collect a schedule of prices and rates for the ice and cold storage so furnished, which schedule of prices and rates shall at all times be subject to regulation by the Public Service Commission."}},{"id":"PH-H4165-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Said grantee shall manufacture and supply ice up to the limit of the capacity of his plant."}},{"id":"PH-H4165-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall change or alter any of said apparatus and appurtenances at his expense whenever the Public Service Commission shall determine that public interest reasonably requires it."}},{"id":"PH-H4165-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the manufacture and distribution of ice in said city and province within five years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall become null and void."}},{"id":"PH-H4165-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, and with the understanding and upon condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H4165-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H4165-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any other individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H4165-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"In consideration of the franchise and rights granted by this Act, the grantee shall pay taxes as provided for under existing laws."}},{"id":"PH-H4165-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Dominador A. Simon a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the City of Cotabato and to Sell Ice and Supply Cold Storage Within the Province and City of Cotabato","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4166"] = {"id":"PH-H4166","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5365_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Lidlidda市","en":"An Act Establishing the Lidlidda Station Hospital in the Municipality of Lidlidda, Province of Ilocos Sur and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing the Lidlidda Station Hospital in the Municipality of Lidlidda, Province of Ilocos Sur and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5365","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5365_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4166-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"As defined in this Act, a station hospital shall mean a small hospital of not more than twenty-five bed-capacity for the management of common medical and maternity cases and surgical emergencies requiring ordinarily a short period of confinement. Cases requiring complicated major surgery and/or elaborate diagnostic examination or specialist treatment may not be confined in this hospital but transferred to regular provincial or regional hospitals."}},{"id":"PH-H4166-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby established in the Municipality of Lidlidda, Province of Ilocos Sur, a station hospital to be known as the Lidlidda Station Hospital with a bed capacity of not less than ten nor more than twenty-five beds."}},{"id":"PH-H4166-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Health shall cause the establishment of the hospital, provide a suitable table of organization of not more than fourteen personnel and promulgate rules and regulations for its maintenance and operation. He may, if the exigency of the service so demands, merge this hospital with local health units in the Municipality of Lidlidda, Province of Ilocos Sur, provided that the public health work of the latter unit will not be impaired."}},{"id":"PH-H4166-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sum of not to exceed fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, maintenance and operation of said hospital during the first fiscal year of its operation. Thereafter, such sums as may be needed, but not to exceed fifty thousand pesos, for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4166-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4167"] = {"id":"PH-H4167","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5366_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Angaki (Quirino)市","en":"An Act Establishing the Angaki (Quirino) Station Hospital in the Municipality of Angaki (Quirino), Province of Ilocos Sur, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing the Angaki (Quirino) Station Hospital in the Municipality of Angaki (Quirino), Province of Ilocos Sur, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5366","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5366_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4167-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"As defined in this Act, a station hospital shall mean a small hospital of not more than twenty-five-bed capacity for the management of common medical and maternity cases and surgical emergencies requiring ordinarily a short period of confinement. Cases requiring complicated major surgery and/or elaborate diagnostic examination or specialist treatment may not be confined in this hospital but transferred to regular provincial or regional hospitals."}},{"id":"PH-H4167-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby established in the Municipality of Angaki (Quirino), Province of Ilocos Sur, a station hospital to be known as Angaki (Quirino) Station Hospital with a bed capacity of not less than ten or more than twenty-five beds."}},{"id":"PH-H4167-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Health shall cause the establishment of this hospital, provide a suitable table of organization of not more than fourteen personnel and promulgate rules and regulations for its maintenance and operation. He may, if the exigency of the service so demands, merge this hospital with local health units in the Municipality of Angaki (Quirino), Province of Ilocos Sur, provided that the public health work of the latter unit will not be impaired."}},{"id":"PH-H4167-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sum of not to exceed fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, maintenance and operation of said hospital during the first fiscal year of its operation. Thereafter, such sums as may be needed, but not to exceed fifty thousand pesos, for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4167-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4168"] = {"id":"PH-H4168","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5367_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Sugpon市","en":"An Act Establishing the Sugpon Station Hospital in the Municipality of Sugpon, Province of Ilocos Sur and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing the Sugpon Station Hospital in the Municipality of Sugpon, Province of Ilocos Sur and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5367","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5367_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4168-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"As defined in this Act, a station hospital shall mean a small hospital of not more than twenty-five bed capacity for the management of common medical and maternity cases and surgical emergencies requiring ordinarily a short period of confinement. Cases requiring complicated major surgery and/or elaborate diagnostic examination or specialist treatment may not be confined in this hospital but transferred to regular provincial or regional hospitals."}},{"id":"PH-H4168-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby established in the Municipality of Sugpon, Province of Ilocos Sur, a station hospital to be known as Sugpon Station Hospital with a bed capacity of not less than ten or more than twenty-five beds."}},{"id":"PH-H4168-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Health shall cause the establishment of this hospital, provide a suitable table of organization of not more than fourteen personnel and promulgate rules and regulations for its maintenance and operation. He may, if the exigency of the service so demands, merge this hospital with local health units in the Municipality of Sugpon, Province of Ilocos Sur, provided that the public health work of the latter unit will not be impaired."}},{"id":"PH-H4168-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sum not to exceed fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, maintenance and operation of said hospital during the first fiscal year of its operation. Thereafter, such sums as may be needed, but not to exceed fifty thousand pesos, for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4168-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4169"] = {"id":"PH-H4169","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5368_1968.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将本格特-碧瑶省学校分区重组为两个学校分区、为各分区配备必要办公人员与额外教职员并为其拨款及为其他目的法案","en":"An Act Reorganize the School Division of the Province of Benguet-Baguio into Two School Divisions, Provide Each Division with the Necessary Division Office Staff and Additional School Personnel, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Reorganize the School Division of the Province of Benguet-Baguio into Two School Divisions, Provide Each Division with the Necessary Division Office Staff and Additional School Personnel, Appropriating Funds Therefor and for Other Purposes"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5368","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5368_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4169-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Provision of existing laws to the contrary notwithstanding, the existing school division of the Province of Benguet-Baguio is hereby reorganized so as to establish for the said province, two school divisions, namely; the Division of City Schools, Baguio City and the Division of Benguet. The existing school division of Benguet-Baguio shall, upon the implementation of this Act, be abolished."}},{"id":"PH-H4169-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education is hereby authorized to effect the reorganization and the creation of the two new school divisions established under this Act and to appoint the necessary division office staff so as to provide for each school division office the following personnel, namely: one division superintendent, one academic superior, and one general education supervisor for each of the following subject areas: English, Pilipino, Science, Social Studies, Mathematics, Industrial Arts, Home Economics, Physical Education, Music and Arts, Adult Education and Evaluation and Guidance: Provided, However, That preference shall be given to present incumbents of the positions hereinabove enumerated as to their choice of assignment in either of the two divisions, after which new appointees may be assigned to the positions as are open, vacant or unfilled by reason of the said reorganization: And Provided, further, That the Secretary of Education shall authorize the appointment of necessary administrative and clerical personnel in the number allowed under existing rules and regulations in each of the respective division offices."}},{"id":"PH-H4169-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Nothing in this Act shall prevent the City Government of Baguio City or the Provincial Government of Benguet form appropriating funds for the employment of such additional personnel as each may deem necessary for each of their respective division offices."}},{"id":"PH-H4169-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education is hereby further authorized to reorganize, on the recommendation of the Director of Public Schools, the school districts in each of the two school divisions created under this Act, and to appoint district supervisors to fill vacancies or new positions resulting therefrom, including the appointment of school principals and barrio head teachers as are necessary to insure that each complete public elementary school has its own principal and each complete primary school in the barrios has its own barrio head teacher."}},{"id":"PH-H4169-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sum of two hundred fifty thousand pesos or so much thereof as may be necessary to carry out the purposes of this Act is hereby appropriated out of any funds in the National Treasury, not otherwise appropriated. Thereafter, the necessary amount to maintain the two school divisions as established and reorganized in accordance with this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H4169-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reorganize the School Division of the Province of Benguet-Baguio into Two School Divisions, Provide Each Division with the Necessary Division Office Staff and Additional School Personnel, Appropriating Funds Therefor and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4170"] = {"id":"PH-H4170","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5369_1968.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予南伊罗戈省维甘工程师 Vicente Villanueva y Florendo 在南伊罗戈省安装、运营电灯、热力、动力系统及制冰与冷藏厂并销售相关产品的特许权法案","en":"An Act Granting Engineer Vicente Villanueva y Florendo of Vigan, Ilocos Sur, a Franchise to Install, Operate and Maintain an Electric Light, Heat, Power System, and Ice and Cold Storage Plants in the Province of Ilocos Sur and to Sell and Distribute Electric Light, Heat, Power, Ice and Supply Cold Storage Therein","orig":"An Act Granting Engineer Vicente Villanueva y Florendo of Vigan, Ilocos Sur, a Franchise to Install, Operate and Maintain an Electric Light, Heat, Power System, and Ice and Cold Storage Plants in the Province of Ilocos Sur and to Sell and Distribute Electric Light, Heat, Power, Ice and Supply Cold Storage Therein"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5369","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5369_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4170-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, and to the provisions of the Constitution, there is granted to Engineer Vicente Villanueva y Florendo of Vigan, Ilocos Sur, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to install, operate and maintain electric light, heat and power system, and ice plant and cold storage for the purpose of generating, distributing electric light, heat, and/or power and manufacturing ice for sale and for supplying cold storage in the Province of Ilocos Sur."}},{"id":"PH-H4170-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power and/or enter into any business agreement with the Rural Electrification Administration, the National Power Corporation and the Rural Electrification Administration, respectively, are hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H4170-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity if his ice plant."}},{"id":"PH-H4170-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission or its legal successor shall determine that public interest reasonably requires it, change or alter any of its apparatus and appurtenances at grantee's expense."}},{"id":"PH-H4170-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"If the grantee shall not commence the generation of electricity, and the manufacture and distribution of ice and electricity in the Province of Ilocos Sur, within two years from the approval of this Act, unless prevented by an Act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall be null and void."}},{"id":"PH-H4170-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This franchise is granted subject to the provisions of the Constitution and Commonwealth Act Numbered One hundred forty-six, as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H4170-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any completing individual association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons or corporation."}},{"id":"PH-H4170-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H4170-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"In consideration of this franchise, the grantee shall pay a franchise tax equivalent to two percent of its gross income."}},{"id":"PH-H4170-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Engineer Vicente Villanueva y Florendo of Vigan, Ilocos Sur, a Franchise to Install, Operate and Maintain an Electric Light, Heat, Power System, and Ice and Cold Storage Plants in the Province of Ilocos Sur and to Sell and Distribute Electric Light, Heat, Power, Ice and Supply Cold Storage Therein","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4171"] = {"id":"PH-H4171","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5370_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Pilar市","en":"An Act Establishing the Pilar Station Hospital in the Municipality of Pilar, Province of Cebu, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing the Pilar Station Hospital in the Municipality of Pilar, Province of Cebu, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5370","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5370_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4171-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"As defined in this Act, a station hospital shall mean a small hospital of not more than twenty-five-bed capacity for the management of common medical and maternity cases and surgical emergencies requiring ordinarily a short period of confinement. Cases requiring complicated major surgery and/or elaborate diagnostic examination or specialist treatment may not be confined in this hospital but transferred to regular provincial or regional hospitals."}},{"id":"PH-H4171-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby established in the Municipality of Pilar, Province of Cebu, a station hospital to be known as Pilar Station Hospital with a bed capacity of not less than ten nor more than twenty-five beds."}},{"id":"PH-H4171-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Health shall cause the establishment of this hospital, provide a suitable table or organization of not more than fourteen personnel and promulgate rules and regulations for its maintenance and operation. He may, if the exigency of the service so demands merge this hospital with local health units in the Municipality of Pilar, Province of Cebu, provided that the public health work of the latter unit will not be impaired."}},{"id":"PH-H4171-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sum not to exceed fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, maintenance and operation of said hospital, during the first fiscal year of its operation. Thereafter, such sums as may be needed, but not to exceed fifty thousand pesos, for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4171-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4172"] = {"id":"PH-H4172","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5371_1968.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Pedro N. Roa 在 Cagayan De Oro 市建设、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting Pedro N. Roa a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in Cagayan De Oro City","orig":"An Act Granting Pedro N. Roa a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in Cagayan De Oro City"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5371","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5371_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4172-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution as well as of Act Numbered Thirty-eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes,\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments and other applicable laws not inconsistent with this Act, Pedro N. Roa is hereby granted for a period of twenty-five years a franchise to construct, establish, maintain and operate, for commercial purposes and in the public interest, radio broadcasting and television stations in Cagayan de Oro City: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting station or one television station be begun within four years from the date of approval of this Act and be completed within five years from said date: Provided, further, That the grantee shall provide public service time to enable the Government, through the said radio broadcasting and television stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use his stations for the broadcasting and/or telecasting of obscene or indecent language, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H4172-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H4172-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast and/or telecast from his stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast shall cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H4172-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H4172-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, natural or juridical, nor merge with any other person without the previous approval of the Congress of the Philippines. Any person, natural or juridical, to which this franchise is sold, transferred or assigned shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to such person."}},{"id":"PH-H4172-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall be subject to pay the same taxes on his real estate, buildings and personal property, exclusive of the franchise, as other persons, natural or juridical, are now or hereafter may be required by law to pay. The grantee shall further be liable to pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H4172-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall file a bond in the amount of ten thousand pesos to warrant the fulfillment of and compliance with the conditions under which the franchise is granted. If after two years from the date of acceptance of this franchise the grantee shall have fulfilled said conditions or soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H4172-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance of this franchise shall be given in writing by the grantee within six months after the approval of this Act. When so accepted, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H4172-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee's radio broadcasting and television stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used under this franchise and issued to the grantee license for such use."}},{"id":"PH-H4172-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"In the event of any competing person, natural or juridical, receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as to the case of said competing person."}},{"id":"PH-H4172-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H4172-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Wherever in this franchise the term \"grantee\" is used, it shall be held and understood to mean Pedro N. Roa, his representatives, successors or assigns, unless the context indicates otherwise."}},{"id":"PH-H4172-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This franchise shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H4172-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Pedro N. Roa a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in Cagayan De Oro City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4173"] = {"id":"PH-H4173","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5372_1968.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 L.N. Agustin Farms，Inc. 在米沙鄢建设、维护和运营无线电广播站的特许经营权法案","en":"An Act Granting L.N. Agustin Farms, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations in the Visayas","orig":"An Act Granting L.N. Agustin Farms, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations in the Visayas"},"level":"law","status":"active","topics":["investment","environment"],"docNumber":"Republic Act No. 5372","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5372_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4173-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, L. N. Agustin Farms, Inc., hereinafter referred to as the grantee, is hereby granted a franchise, which shall continue in force for a period of twenty-five years from the approval of this Act, to construct, maintain and operate, for commercial purposes and in the public interest, radio broadcasting stations in the Visayas: Provided, That the franchise shall be void unless the construction of at least one radio broadcasting station be begun within three years from the date of approval of this Act, and be completed within five years from the said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use the stations for the broadcasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H4173-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines may permit, subject to such rules and regulations as he may promulgate, the location on the public domain of any radio station which the grantee may construct."}},{"id":"PH-H4173-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Thirty-nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, as are applicable to radio broadcasting stations shall be applied."}},{"id":"PH-H4173-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"As a condition to the granting of this franchise, the grantee shall execute a bond in favor of the Government of the Philippines, in the sum of fifty thousand pesos, in form and with sureties, satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee's obligations hereunder during the first three years of the life of this franchise. If, after four years from the date of acceptance of this franchise, the grantee shall have fulfilled said obligations, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H4173-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Acceptance of this franchise shall be given in writing within six months after the approval of this Act. When so accepted by the grantee and upon the approval of the bond aforesaid by the Secretary of Public Works and Communications, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H4173-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee's radio broadcasting stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H4173-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than these herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee, as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H4173-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall pay the same taxes on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now paying or hereafter may be required by law to pay. The grantee shall pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H4173-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or action, arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H4173-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H4173-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein at cost, less reasonable depreciation."}},{"id":"PH-H4173-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H4173-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal for such speech, play, act or scene or other matter; Provided, That the grantee, during any broadcast shall cut off from the air the speech, play, act or scene or other matter being broadcast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H4173-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation, or other commercial or legal entity."}},{"id":"PH-H4173-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Whenever in this franchise the term \"grantee\" is used, it shall be held and understood to mean the L. N. Agustin Farms, Inc., its representatives, successors or assigns, unless the context indicates otherwise."}},{"id":"PH-H4173-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This franchise shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H4173-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting L.N. Agustin Farms, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations in the Visayas","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4174"] = {"id":"PH-H4174","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5373_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Five Hundred Thousand Pesos for the Expenses of the Conference of the Asian Parliamentarians' Union to be Held in the City of Manila in Nineteen Hundred Sixty-Eight","orig":"An Act Appropriating Five Hundred Thousand Pesos for the Expenses of the Conference of the Asian Parliamentarians' Union to be Held in the City of Manila in Nineteen Hundred Sixty-Eight"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 5373","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5373_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4174-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of five hundred thousand pesos, or so much thereof as may be necessary, is appropriated, out of any funds in the National Treasury not otherwise appropriated, for the expenses of the conference of the Asian Parliamentarians' Union which will be held in the City of Manila, in nineteen hundred sixty-eight."}},{"id":"PH-H4174-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4175"] = {"id":"PH-H4175","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5374_1968.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Bay Transport Co.，Inc. 在菲律宾境内建设、设立、维护和运营私人固定点对点、海岸、陆基、航空与陆上移动无线电台的临时许可的法案","en":"An Act Granting Bay Transport Co., Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Bay Transport Co., Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5374","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5374_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4175-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Bay Transport Co., Inc. a temporary permit to construct, establish, maintain and operate in the Philippines, at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point, coastal, and land based, aeronautical and land mobile radio stations for the reception and transmission of wireless messages by radiotelegraph or radiotelephone, each to be provided with a radio transmitting apparatus and radio receiving apparatus."}},{"id":"PH-H4175-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said radio stations or any of them on lands of the public domain under terms and conditions as he may prescribe."}},{"id":"PH-H4175-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established a similar service at the places selected by the grantee, and is granted on the condition that the same shall be void unless the construction of at least one station be begun within one year from the date of approval of this Act and completed within two years from said date."}},{"id":"PH-H4175-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate said radio stations at such places within the Philippines as the interest of the grantee and its trade and business may justify."}},{"id":"PH-H4175-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee frequencies and wave lengths to be used thereunder, but the grantee may use the international distress frequency of eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H4175-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H4175-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H4175-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, or the rights or privileges acquired thereunder to any person, natural or juridical, nor merge with any other persons, without the approval of the Congress of the Philippines, in which event, any person, natural or juridical, to which this temporary permit may be sold, transferred or assigned, shall be subject to existing laws and regulations, or those that may hereafter be enacted; and any person to which this temporary permit is sold, transferred or assigned, shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if said temporary permit had been originally granted to such persons."}},{"id":"PH-H4175-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H4175-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This temporary permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H4175-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Bay Transport Co., Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4176"] = {"id":"PH-H4176","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5375_1968.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Associated Agricultural Activities 在菲律宾境内建设、设立、运营私人固定点对点、海岸、航空、陆基与陆上移动无线电台的临时许可法案","en":"An Act Granting Associated Agricultural Activities, Inc. a Temporary Permit to Construct, Establish, Operate and Maintain Private Fixed Point-to-Point, Coastal, Aeronautical, Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Associated Agricultural Activities, Inc. a Temporary Permit to Construct, Establish, Operate and Maintain Private Fixed Point-to-Point, Coastal, Aeronautical, Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 5375","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5375_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4176-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Associated Agricultural Activities, Inc. a temporary permit to construct, establish, operate and maintain in the Philippines, at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point, coastal, aeronautical, land-based and land mobile radio stations for the reception and transmission of wireless messages by radiotelegraph or radiotelephone, each to be provided with a radio transmitting apparatus and radio receiving apparatus."}},{"id":"PH-H4176-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said radio stations or any of them on lands of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H4176-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, operate and maintain said radio stations at such places within the Philippines as the interest of the grantee and of its trade and business may justify."}},{"id":"PH-H4176-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H4176-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"No fees shall be charged as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee's business only."}},{"id":"PH-H4176-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H4176-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands, or action arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H4176-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Any person, natural or juridical, to which this temporary permit may be sold, transferred or assigned, shall be subject to the corporation laws of the Philippines, now existing or hereafter enacted, and any person to which this temporary permit is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to such person."}},{"id":"PH-H4176-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H4176-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Whenever in this permit the term \"grantee\" is used, it shall be held and understood to mean Associated Agricultural Activities, Inc., its representatives, successors or assigns, unless the context indicates otherwise."}},{"id":"PH-H4176-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H4176-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Associated Agricultural Activities, Inc. a Temporary Permit to Construct, Establish, Operate and Maintain Private Fixed Point-to-Point, Coastal, Aeronautical, Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4177"] = {"id":"PH-H4177","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5376_1968.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Atlas 综合矿业开发公司在菲律宾境内建设、维护和运营私人固定点、航空、陆基、船舶与信标站的临时许可的法案","en":"An Act Granting Atlas Consolidated Mining and Development Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed, Aeronautical Fixed, Aeronautical, Land Mobile/Portable, Based, Land Mobile/Portable, Coast, Ship, Survival Craft, Radio Determination and Radio Beacon Stations for the Reception and Transmission of Wireless Radiotelegraph or Radiotelephone in the Philippines","orig":"An Act Granting Atlas Consolidated Mining and Development Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed, Aeronautical Fixed, Aeronautical, Land Mobile/Portable, Based, Land Mobile/Portable, Coast, Ship, Survival Craft, Radio Determination and Radio Beacon Stations for the Reception and Transmission of Wireless Radiotelegraph or Radiotelephone in the Philippines"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 5376","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5376_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4177-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Atlas Consolidated Mining and Development Corporation, its successors and assigns, a temporary permit to construct, maintain and operate in such places in the Philippines where it operates or transacts its business or render its services, subject to the approval of the Secretary of Public Works and Communications, or any licensing authority private fixed, aeronautical fixed, aeronautical, land mobile/portable, based, land mobile/portable, coast, ship, survival craft, radio determination and radio beacon stations for the reception and/or transmission of wireless radiotelegraph or radiotelephone, inclusive of but not limited to facsimile, radioteletype, nationally and internationally, each station to be provided with radio transmitting and receiving equipment, as necessary."}},{"id":"PH-H4177-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the grantee, its successors or assigns, conducts its business or services at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of at least two radio stations be begun within two years from the date of the approval of this Act."}},{"id":"PH-H4177-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic public telecommunication business in the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee, its successors or assigns, the right to construct, install, maintain and operate its radio stations herein granted at the places above-mentioned for the primary purpose of promoting and protecting its business and other interests."}},{"id":"PH-H4177-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall be engaged in communications regarding the grantee's business interests."}},{"id":"PH-H4177-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its radio stations herein granted in the very low frequency, low frequency, medium frequency, high frequency, very high frequency, ultra high frequency, super high frequency and extreme high frequency that shall be assigned to it by the Secretary of Public Works and Communications, or by any licensing authority."}},{"id":"PH-H4177-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and private coastal radio stations or any of them on lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H4177-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall be construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H4177-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H4177-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines."}},{"id":"PH-H4177-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use or possession thereof by any department of the Government upon just compensation."}},{"id":"PH-H4177-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H4177-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"In the event of any individual, partnership or corporation receiving from the Congress a similar permit in which there shall be any term or terms more favorable than those herein granted, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said individual, partnership or corporation."}},{"id":"PH-H4177-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Atlas Consolidated Mining and Development Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed, Aeronautical Fixed, Aeronautical, Land Mobile/Portable, Based, Land Mobile/Portable, Coast, Ship, Survival Craft, Radio Determination and Radio Beacon Stations for the Reception and Transmission of Wireless Radiotelegraph or Radiotelephone in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4178"] = {"id":"PH-H4178","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5377_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将宿务省圣弗朗西斯科市镇圣伊西德罗村最长街道命名为Quirino Maningo公路的法案","en":"An Act Naming the Longest Street in Barrio San Isidro, Municipality of San Francisco, Province of Cebu, the Quirino Maningo Road","orig":"An Act Naming the Longest Street in Barrio San Isidro, Municipality of San Francisco, Province of Cebu, the Quirino Maningo Road"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5377","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5377_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4178-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The longest street in Barrio San Isidro, Municipality of San Francisco, Province of Cebu, is hereby named Quirino Maningo Road."}},{"id":"PH-H4178-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Naming the Longest Street in Barrio San Isidro, Municipality of San Francisco, Province of Cebu, the Quirino Maningo Road","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4179"] = {"id":"PH-H4179","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5378_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为南哥打巴托省增设4个Assistant 省立 Fiscal职位，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Creating Four Positions of Assistant Provincial Fiscal in the Province of South Cotabato, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating Four Positions of Assistant Provincial Fiscal in the Province of South Cotabato, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5378","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5378_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4179-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals, is hereby amended by inserting, after its provisions regarding assistant provincial fiscals for the Province of Cotabato, the following:\n\"South Cotabato, four assistant provincial fiscals;\""}},{"id":"PH-H4179-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Four Positions of Assistant Provincial Fiscal in the Province of South Cotabato, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4180"] = {"id":"PH-H4180","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5379_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在南哥打巴托省Glan市镇设立职业中学，名称为Glan职业中学，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a Vocational High School in the Municipality of Glan, Province of South Cotabato, to be Known as Glan Vocational High School and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Vocational High School in the Municipality of Glan, Province of South Cotabato, to be Known as Glan Vocational High School and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5379","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5379_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4180-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a vocational high school in the Municipality of Glan, Province of South Cotabato, to be known as Glan Vocational High School."}},{"id":"PH-H4180-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H4180-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred sixty-nine. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4180-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Vocational High School in the Municipality of Glan, Province of South Cotabato, to be Known as Glan Vocational High School and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4181"] = {"id":"PH-H4181","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5380_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Hinunangan市","en":"An Act Establishing a National Agricultural and Vocational School in the Municipality of Hinunangan, Province of Southern Leyte, to be Known as Hinunangan Agricultural and Vocational School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a National Agricultural and Vocational School in the Municipality of Hinunangan, Province of Southern Leyte, to be Known as Hinunangan Agricultural and Vocational School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 5380","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5380_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4181-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established under the direct supervision of the Director of Vocational Education, a national agricultural and vocational school in the Municipality of Hinunangan, Province of Southern Leyte, to be known as Hinunangan Agricultural and Vocational School."}},{"id":"PH-H4181-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred and sixty-nine. Such sums as may be necessary in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H4181-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4182"] = {"id":"PH-H4182","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5381_1968.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予 Miguel S. Sioson 在巴丹省 Orani 市镇建设、运营和维护制冰厂与冷藏库特许权的法案","en":"An Act Granting Miguel S. Sioson a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Orani, Province of Bataan","orig":"An Act Granting Miguel S. Sioson a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Orani, Province of Bataan"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5381","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5381_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4182-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in this Act and in Commonwealth Act Numbered One hundred forty-six, as amended, and to the provisions of the Constitution, there is granted to Miguel S. Sioson for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, operate and maintain and ice plant and cold storage in the Municipality of Orani, Province of Bataan, for the purpose of manufacturing ice for distribution and sale, and of supplying cold storage therein, and to charge and collect a schedule of prices and rates therefor which schedule of prices shall at all times be subject to regulation by the Public Service Commission or its legal successor."}},{"id":"PH-H4182-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall install, maintain and operate ice plant and cold storage in the Municipality of Orani, Province of Bataan: Provided, However, That the total daily output of the ice plant so installed and maintained shall not exceed sixty tons and that the cold storage so installed and maintained shall not exceed a total capacity of five hundred tons."}},{"id":"PH-H4182-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect. Whenever the Public Service Commission shall determine that public interest reasonably requires it, the grantee shall change or alter any of the apparatus and appurtenances at grantee's expense."}},{"id":"PH-H4182-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the construction of at least one ice plant and cold storage within two years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall become null and void."}},{"id":"PH-H4182-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H4182-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records, and accounts of the grantee shall always be open to inspection by the municipal treasurer or his authorized representatives, and it shall be the duty of the grantee to submit to the municipality treasurer quarterly reports in duplicate showing the gross receipts for the past quarter, one of which shall be forwarded by the municipal treasurer to the Auditor General, who shall keep the same on file."}},{"id":"PH-H4182-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In consideration of the franchise and rights hereby granted, the grantee shall pay a franchise tax equal to five per centum of the gross earnings under this franchise, three per centum of which shall accrue to the National Government and two per centum to the municipality where the franchise is in operation."}},{"id":"PH-H4182-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, only with respect to the fixing of rates."}},{"id":"PH-H4182-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"In the event of any competing individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H4182-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Miguel S. Sioson a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Orani, Province of Bataan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4183"] = {"id":"PH-H4183","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5382_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"为第十六司法区增设一名法官，主持南哥打巴托初审法院，常设于南哥打巴托省Koronadal市镇，为此修订1948年《司法法》第49、50、52条","en":"An Act Providing for One Additional Judge for the Sixteenth Judicial District to Preside Over the Court of First Instance of South Cotabato with Permanent Station in the Municipality of Koronadal, Province of South Cotabato, Amending for the Purpose Sections Forty-Nine, Fifty and Fifty-Two of the Judiciary Act of 1948","orig":"An Act Providing for One Additional Judge for the Sixteenth Judicial District to Preside Over the Court of First Instance of South Cotabato with Permanent Station in the Municipality of Koronadal, Province of South Cotabato, Amending for the Purpose Sections Forty-Nine, Fifty and Fifty-Two of the Judiciary Act of 1948"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5382","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5382_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4183-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sixteenth subparagraph of Section forty-nine of Republic Act Numbered Two hundred ninety-six, known as the Judiciary Act of 1948, as amended, is further amended to read as follows:\n\"The Sixteenth Judicial District, of the Provinces of Davao del Norte, Davao del Sur, Davao Oriental and the City of Davao, the Provinces of Cotabato, South Cotabato, and the City of Cotabato and Occidental Misamis, Ozamis City, the Provinces of Zamboanga del Norte and Zamboanga del Sur, Zamboanga City, Basilan City, and the Province of Sulu."}},{"id":"PH-H4183-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sixteenth paragraph of Section fifty of the same Act, as amended, is further amended to read as follows:\n\"Nineteen judges shall be commissioned for the Sixteenth Judicial District. Four judges shall preside over the Courts of First Instance of the Provinces of Davao del Norte, Davao del Sur, Davao Oriental, and Davao City, to be known as judges of the first, second, third and fourth branches thereof; three judges shall preside over the Court of First Instance of Cotabato, to be known as judges of the first, second and third branches thereof; two judges shall preside over the Court of First Instance of South Cotabato, to be known as judges of the first and second branches thereof, respectively; three judges shall preside over the Courts of First Instance of Occidental Misamis and Ozamis City, to be known as judges of the first, second and third branches thereof; two judges shall preside over the Court of First Instance of Zamboanga del Norte, to be known as judges of the first and second branches thereof; one judge shall preside over the Court of First Instance of Zamboanga del Sur; one judge shall preside over the Court of First Instance of Zamboanga City; one judge shall preside over the Court of First Instance of Basilan City; and two judges shall preside over the Court of First Instance of Sulu, to be known as judges of the first and second branches thereof."}},{"id":"PH-H4183-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The fifteenth subparagraph of the second paragraph of Section fifty-two of the same Act, as amended, is further amended to read as follows:\n\"For the Sixteenth Judicial District, three judges shall be stationed in the City of Davao; one judge in the Municipality of Mati, Province of Davao Oriental; one judge shall be stationed in the City of Cotabato; one judge each shall be stationed in the Municipalities of Koronadal and General Paulino Santos, Province of South Cotabato; one judge each shall be stationed in the Municipalities of Pagalungan and Sultan sa Barongis, Province of Cotabato; two judges shall be stationed in the Municipality of Oroquieta, Province of Occidental Misamis; one judge shall be stationed in Ozamis City; two judges in the Municipality of Dipolog, Province of Zamboanga del Norte; one judge in the Municipality of Pagadian, Province of Zamboanga del Sur; one judge in the City of Zamboanga; one judge in the City of Basilan; one judge in the Municipality of Jolo, Province of Sulu; and one judge in the Municipality of Siasi, same province."}},{"id":"PH-H4183-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of eighty thousand pesos or so much thereof as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H4183-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for One Additional Judge for the Sixteenth Judicial District to Preside Over the Court of First Instance of South Cotabato with Permanent Station in the Municipality of Koronadal, Province of South Cotabato, Amending for the Purpose Sections Forty-Nine, Fifty and Fifty-Two of the Judiciary Act of 1948","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4184"] = {"id":"PH-H4184","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5383_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛省卡巴图安市镇赫利库翁卢萨亚村赫帕卡村学校的名称变更为Pablo Muyuela村学校的法案","en":"An Act Changing the Name of Jepaca Barrio School in Barrio Jelicuon Lusaya, Municipality of Cabatuan, Province of Iloilo, to Pablo Muyuela Barrio School","orig":"An Act Changing the Name of Jepaca Barrio School in Barrio Jelicuon Lusaya, Municipality of Cabatuan, Province of Iloilo, to Pablo Muyuela Barrio School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5383","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5383_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4184-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Jepaca Barrio School in Barrio Jelicuon Lusaya, Municipality of Cabatuan, Province of Iloilo, is hereby changed to Pablo Muyuela Barrio School."}},{"id":"PH-H4184-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Jepaca Barrio School in Barrio Jelicuon Lusaya, Municipality of Cabatuan, Province of Iloilo, to Pablo Muyuela Barrio School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4185"] = {"id":"PH-H4185","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5384_1968.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予 Sylvia G. Gumabao 在伊莎贝拉省 Santiago 与 Echague 市镇建设、维护和运营制冰厂与冷藏库并在该省各市镇销售冰和供应冷藏的特许权法案","en":"An Act Granting Sylvia G. Gumabao a Franchise to Construct, Maintain, and Operate an Ice Plant and Cold Storage in the Municipalities of Santiago and Echague, Province of Isabela, and to Sell and Distribute Ice so Manufactured and Furnish Cold Storage Therein and in the Municipalities of Alicia, Angadanan, Cauayan, Cabatuan, San Mateo, Ramon, Cordon, Jones, San Agustin, San Guillermo and San Isidro, All in the Province of Isabela","orig":"An Act Granting Sylvia G. Gumabao a Franchise to Construct, Maintain, and Operate an Ice Plant and Cold Storage in the Municipalities of Santiago and Echague, Province of Isabela, and to Sell and Distribute Ice so Manufactured and Furnish Cold Storage Therein and in the Municipalities of Alicia, Angadanan, Cauayan, Cabatuan, San Mateo, Ramon, Cordon, Jones, San Agustin, San Guillermo and San Isidro, All in the Province of Isabela"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5384","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5384_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4185-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions established in this Act, and the provisions of Commonwealth Act Numbered One hundred and forty-six, as amended, and of the Constitution, applicable thereto, there is hereby granted to Sylvia G. Gumabao, hereinafter called the grantee, her successors or assigns, for a period of twenty-five years from the approval of this Act, the right and privilege to construct, operate and maintain a fifty-ton ice plant and cold storage in the municipalities of Santiago and Echague, Province of Isabela, for the purpose of manufacturing and distributing ice within said municipalities and to sell the ice manufactured therein and in the municipalities of Alicia, Angadanan, Cauayan, Cabatuan, San Mateo, Ramon, Cordon, Jones, San Agustin, San Guillermo and San Isidro, all in the Province of Isabela, and to render cold storage service and facilities in the same municipalities and to charge and collect a schedule of rates and prices for the ice so manufactured, distributed and sold, which schedule of rates and prices shall at all times be subject to regulations by the Public Service Commission."}},{"id":"PH-H4185-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, only with respect to fixing rates and with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H4185-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall change or alter any of said apparatus and appurtenances at her expense whenever the Public Service Commission shall determine that public interest reasonably requires it."}},{"id":"PH-H4185-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the manufacture and distribution of ice in said municipalities within two years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall become null and void."}},{"id":"PH-H4185-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee is authorized by this Act to mortgage the franchise with the Development Bank of the Philippines in securing an industrial loan, without the previous approval of the Congress."}},{"id":"PH-H4185-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H4185-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any other individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H4185-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"In consideration of this franchise the grantee shall pay a franchise tax equivalent to two percent of its gross income."}},{"id":"PH-H4185-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"In consideration of the franchise and rights granted by this Act, the grantee shall pay a franchise tax as provided for under existing laws."}},{"id":"PH-H4185-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Sylvia G. Gumabao a Franchise to Construct, Maintain, and Operate an Ice Plant and Cold Storage in the Municipalities of Santiago and Echague, Province of Isabela, and to Sell and Distribute Ice so Manufactured and Furnish Cold Storage Therein and in the Municipalities of Alicia, Angadanan, Cauayan, Cabatuan, San Mateo, Ramon, Cordon, Jones, San Agustin, San Guillermo and San Isidro, All in the Province of Isabela","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
