  FT["PH-H4187"] = {"id":"PH-H4187","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5386_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第2646号共和国法第1条第（f） 与 （i）目（经修正）的法案","en":"An Act Amending Subparagraphs (f) and (i), Section One of Republic Act Numbered Twenty-Six Hundred Forty-Six, as Amended","orig":"An Act Amending Subparagraphs (f) and (i), Section One of Republic Act Numbered Twenty-Six Hundred Forty-Six, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5386","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5386_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4187-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subparagraphs (f) and (i), Section one of Republic Act Numbered Twenty-six hundred forty-six, as amended, is further amended to read as follows:\n\"(f) Region No. 6 comprises the Provinces of Camarines Norte, Camarines Sur, Albay, Sorsogon, Catanduanes and Masbate and the City of Naga, with regional headquarters at Naga City.\n\"(i) Region No. 9 comprises the Provinces of Samar, Surigao del Norte, Surigao del Sur, Leyte and Leyte del Sur and the Cities of Calbayog, Tacloban and Ormoc, with regional headquarters at Tacloban City.\""}},{"id":"PH-H4187-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Subparagraphs (f) and (i), Section One of Republic Act Numbered Twenty-Six Hundred Forty-Six, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4188"] = {"id":"PH-H4188","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5387_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将新怡诗夏省划分为两个公路工程区并授权拨款的法案","en":"An Act Constituting the Province of Nueva Ecija into Two Highway Engineering Districts, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Constituting the Province of Nueva Ecija into Two Highway Engineering Districts, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5387","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5387_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4188-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the Province of Nueva Ecija is hereby constituted into two highway engineering districts. The municipalities comprising the first and second representative districts shall likewise comprise the first and second highway engineering districts thereof respectively."}},{"id":"PH-H4188-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Each of the two highway engineering districts shall have one highway district engineer and such other personnel who shall be appointed in accordance with existing laws and regulations."}},{"id":"PH-H4188-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of six hundred thousand pesos is hereby authorized to be appropriated, out of any funds appropriated for public works projects for the Province of Nueva Ecija, to carry into effect the provisions of this Act."}},{"id":"PH-H4188-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Constituting the Province of Nueva Ecija into Two Highway Engineering Districts, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4189"] = {"id":"PH-H4189","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5388_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"豁免家庭工业某些工人适用第602号共和国法（经修正）的规定，为此进一步修订该法第3条（d）项的法案","en":"An Act Exempting Certain Workers in Cottage Industries from the Provisions of Republic Act Numbered Six Hundred Two, Further Amending for the Purpose Subsection (d) of Section Three of Said Act, as Amended","orig":"An Act Exempting Certain Workers in Cottage Industries from the Provisions of Republic Act Numbered Six Hundred Two, Further Amending for the Purpose Subsection (d) of Section Three of Said Act, as Amended"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 5388","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5388_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4189-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subsection (d) of Section three of Republic Act Numbered Six hundred two, as amended by Republic Act Numbered Four thousand one hundred eighty, is hereby further amended to read as follows:\n\"(d) This Act shall not apply to farm tenancy, domestic servants and persons working in their respective homes in any cottage industry registered under the provisions of Republic Act Numbered Three thousand four hundred seventy.\""}},{"id":"PH-H4189-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Exempting Certain Workers in Cottage Industries from the Provisions of Republic Act Numbered Six Hundred Two, Further Amending for the Purpose Subsection (d) of Section Three of Said Act, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4190"] = {"id":"PH-H4190","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5389_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为第十一司法区增设一名法官主持阿克兰初审法院，常设于阿克兰省Ibajay市镇，为此修订1948年《司法法》第50条与第52条的法案","en":"An Act Providing for One Additional Judge for the Eleventh Judicial District to Preside Over the Court of First Instance of Aklan with Permanent Station in the Municipality of Ibajay, Province of Aklan, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948","orig":"An Act Providing for One Additional Judge for the Eleventh Judicial District to Preside Over the Court of First Instance of Aklan with Permanent Station in the Municipality of Ibajay, Province of Aklan, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5389","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5389_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4190-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The eleventh paragraph of Section fifty of Republic Act Numbered Two hundred ninety-six, known as \"The Judiciary Act of 1948,\" as amended, is further amended to read as follows:\n\"Sixteen judges shall be commissioned for the Eleventh Judicial District. Three judges shall preside over the Courts of First Instance of Capiz and Roxas City and shall be known as judges of the first, second and third branches thereof, respectively; one judge shall preside over the Court of First Instance of the Province of Romblon; one judge shall preside over the Court of First Instance of Marinduque; three judges shall preside over the Court of First Instance of Aklan and shall be known as judges of the first, second and third branches thereof respectively; seven judges shall preside over the Courts of First Instance of the Province of Iloilo and the City of Iloilo and shall be known as the judges of the first, second, third, fourth, fifth, sixth and seventh branches thereof, respectively; and one judge shall preside over the Court of First Instance of the Province of Antique.\""}},{"id":"PH-H4190-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The eleventh subparagraph of the second paragraph of Section fifty-two of the same Act, as amended, is further amended to read as follows:\n\"For the Eleventh Judicial District, two judges shall be stationed in Roxas City; one judge in the Municipality of Mambusao, Province of Capiz; one judge in the Municipality of Romblon, Province of Romblon; one judge in the Municipality of Boac, Province of Marinduque; two judges in the Municipality of Kalibo, Province of Aklan; one judge in the Municipality of Ibajay, same province; seven judges in the City of Iloilo; and one judge in the Municipality of San Jose de Buenavista, Province of Antique.\""}},{"id":"PH-H4190-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of sixty thousand pesos or so much thereof as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H4190-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for One Additional Judge for the Eleventh Judicial District to Preside Over the Court of First Instance of Aklan with Permanent Station in the Municipality of Ibajay, Province of Aklan, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4191"] = {"id":"PH-H4191","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5390_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将保和省塔利邦市镇南圣何塞村的名称变更为圣尼诺村的法案","en":"An Act Changing the Name of Barrio San Jose Sur in the Municipality of Talibon, Province of Bohol, to Barrio Santo Niño","orig":"An Act Changing the Name of Barrio San Jose Sur in the Municipality of Talibon, Province of Bohol, to Barrio Santo Niño"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5390","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5390_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4191-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio San Jose Sur in the Municipality of Talibon, Province of Bohol, is hereby changed to Barrio Santo Niño."}},{"id":"PH-H4191-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Barrio San Jose Sur in the Municipality of Talibon, Province of Bohol, to Barrio Santo Niño","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4192"] = {"id":"PH-H4192","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5391_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在南哥打巴托省桑托斯将军城市镇设立胸科诊所并授权为此拨款的法案","en":"An Act Providing for the Establishment of a Chest Clinic in the Municipality of General Santos, Province of South Cotabato, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Chest Clinic in the Municipality of General Santos, Province of South Cotabato, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5391","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5391_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4192-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Health Services, a chest clinic in the Municipality of General Santos, Province of South Cotabato, to be known as the South Cotabato Chest Clinic. This clinic shall attend to all forms of chest diseases especially pulmonary tuberculosis."}},{"id":"PH-H4192-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue such rules and regulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H4192-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said clinic during the fiscal year nineteen hundred sixty-nine. Such sum as may be necessary for the same purpose in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H4192-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Chest Clinic in the Municipality of General Santos, Province of South Cotabato, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4193"] = {"id":"PH-H4193","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5392_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第4020号共和国法第1条的法案","en":"An Act Amending Section One of Republic Act Numbered Forty Hundred Twenty","orig":"An Act Amending Section One of Republic Act Numbered Forty Hundred Twenty"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5392","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5392_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4193-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Forty hundred twenty is hereby amended to read as follows:\n\"Sec. 1. There is hereby granted to Virginia Development Corporation (VIRDECOR), its successors or assigns, a temporary permit to construct, maintain and operate within the Philippines, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land-based and land-mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus.\""}},{"id":"PH-H4193-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section One of Republic Act Numbered Forty Hundred Twenty","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4194"] = {"id":"PH-H4194","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5393_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权 Jesus B. Pacquing 将其特许权转让或抵押给任何政府所有或控制的金融及/或银行机构的法案","en":"An Act Authorizing Jesus B. Pacquing to Assign or Mortgage His Franchise to Any Government-Owned or Controlled Financial and/or Banking Institution","orig":"An Act Authorizing Jesus B. Pacquing to Assign or Mortgage His Franchise to Any Government-Owned or Controlled Financial and/or Banking Institution"},"level":"law","status":"active","topics":["investment","tax"],"docNumber":"Republic Act No. 5393","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5393_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4194-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, Jesus B. Pacquing is hereby authorized to assign or mortgage his franchise granted under Republic Act Numbered Forty-three hundred and forty-four, to any government-owned or controlled financial and/or banking institution: Provided, However, That the machineries and equipment used in the business are also mortgaged together with the franchise."}},{"id":"PH-H4194-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing Jesus B. Pacquing to Assign or Mortgage His Franchise to Any Government-Owned or Controlled Financial and/or Banking Institution","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4195"] = {"id":"PH-H4195","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5394_1968.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予 Herminio S. Pilar 在马尼拉市建设、运营和维护制冰厂与冷藏库并销售冰和供应冷藏服务的特许权法案","en":"An Act Granting Herminio S. Pilar a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Manila and to Sell Ice and Supply Cold Storage Therein","orig":"An Act Granting Herminio S. Pilar a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Manila and to Sell Ice and Supply Cold Storage Therein"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5394","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5394_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4195-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in this Act and in Commonwealth Act Numbered One hundred forty-six, as amended, and to the provisions of the Constitution, there is hereby granted to Herminio S. Pilar, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an ice plant and cold storage in the City of Manila, for the purpose of manufacturing ice for distribution and sale, and for supplying cold storage therein and to charge and collect a schedule of prices and rates therefor which schedule of prices shall at all times be subject to regulation by the Public Service Commission or its legal successors."}},{"id":"PH-H4195-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of his plant."}},{"id":"PH-H4195-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect. Whenever the Public Service Commission shall determine that public interest reasonably requires it, the grantee shall change or alter any of the apparatus and appurtenances at grantee's expense, and should the demand for ice at any time increase beyond the capacity of the plant of the grantee to supply the same, said capacity of the plant shall be increased by the grantee to meet such demand and in accordance with the decision of the Public Service Commission or its legal successor."}},{"id":"PH-H4195-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the construction of his ice plant and cold storage within two years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall become null and void."}},{"id":"PH-H4195-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H4195-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to inspection by the city treasurer or his authorized representatives, and it shall be the duty of the grantee to submit to the city treasurer quarterly reports in duplicate showing the gross receipts for the past quarter, one of which shall be forwarded by the city treasurer to the Auditor General who shall keep the same on file."}},{"id":"PH-H4195-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In consideration of the franchise and rights hereby granted, the grantee shall pay a franchise tax equal to five per centum of the gross earnings under this franchise, two per centum of which shall accrue to the National Government and three per centum to the city where the franchise is in operation."}},{"id":"PH-H4195-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, only with respect to the fixing of rates."}},{"id":"PH-H4195-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"In the event of any competing individual, association of persons, of corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H4195-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Herminio S. Pilar a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Manila and to Sell Ice and Supply Cold Storage Therein","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4196"] = {"id":"PH-H4196","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5395_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将马斯巴特省 马斯巴特市镇马斯巴特北小学的名称变更为Amancio Aguilar 小学的法案","en":"An Act Changing the Name of Masbate North Elementary School in the Municipality of Masbate, Province of Masbate, to Amancio Aguilar Elementary School","orig":"An Act Changing the Name of Masbate North Elementary School in the Municipality of Masbate, Province of Masbate, to Amancio Aguilar Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5395","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5395_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4196-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Masbate North Elementary School in the Municipality of Masbate, Province of Masbate, is hereby changed to Amancio Aguilar Elementary School."}},{"id":"PH-H4196-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Masbate North Elementary School in the Municipality of Masbate, Province of Masbate, to Amancio Aguilar Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4197"] = {"id":"PH-H4197","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5396_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将马斯巴特省 马斯巴特市镇马斯巴特南小学的名称变更为Jose Zurbito，Sr. 小学的法案","en":"An Act Changing the Name of Masbate South Elementary School in the Municipality of Masbate, Province of Masbate, to Jose Zurbito, Sr. Elementary School","orig":"An Act Changing the Name of Masbate South Elementary School in the Municipality of Masbate, Province of Masbate, to Jose Zurbito, Sr. Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5396","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5396_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4197-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Masbate South Elementary School in the Municipality of Masbate, Province of Masbate, is hereby changed to Jose Zurbito, Sr. Elementary School."}},{"id":"PH-H4197-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Masbate South Elementary School in the Municipality of Masbate, Province of Masbate, to Jose Zurbito, Sr. Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4198"] = {"id":"PH-H4198","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5397_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在南哥打巴托省Surala市镇设立医院，名称为Surala总医院，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a Hospital in the Municipality of Surala, Province of South Cotabato, to be Known as Surala General Hospital, and Authorizing the Appropriations of Funds Therefor","orig":"An Act Providing for the Establishment of a Hospital in the Municipality of Surala, Province of South Cotabato, to be Known as Surala General Hospital, and Authorizing the Appropriations of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5397","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5397_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4198-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Director of Medical Services a hospital in the Municipality of Surala, Province of South Cotabato, to be known as the Surala General Hospital to serve the medical needs of the new Province of South Cotabato."}},{"id":"PH-H4198-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-nine. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4198-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Hospital in the Municipality of Surala, Province of South Cotabato, to be Known as Surala General Hospital, and Authorizing the Appropriations of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4199"] = {"id":"PH-H4199","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5398_1968.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Funds for the Construction of National Buildings on Constitution Hill, Quezon City, and for Other Related Purposes","orig":"An Act Appropriating Funds for the Construction of National Buildings on Constitution Hill, Quezon City, and for Other Related Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5398","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5398_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4199-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of two hundred million pesos, or so much thereof as may be necessary, is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, and/or from the proceeds of bond issues and/or loans which are hereby authorized, for the architectural and engineering services, construction and completion of the national buildings on Constitution Hill in Quezon City, including the improvement of grounds and thoroughfares thereof, subject to the provisions hereinafter set forth: Provided, That the proceeds of bond issues shall not exceed thirty percent of the total loans herein authorized."}},{"id":"PH-H4199-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The national buildings herein referred to in the next preceding section shall consist of the Legislative Group, the Executive Group, and the Judiciary Group, and other related structures."}},{"id":"PH-H4199-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"For the architectural and engineering services, construction and completion of the above-mentioned buildings and other related structures, the Secretary of the Department of Public Works and Communications through the Director of Public Works, is hereby authorized to enter into contracts with private persons, natural or juridical, for the architectural and engineering services and/or construction of said structures on Constitution Hill, in consultation with and approval of the Senate President and the Speaker of the House of Representatives of the Congress of the Philippines and the Chief Justice of the Supreme Court as regards their respective Building Groups, and upon prior approval of the President of the Philippines."}},{"id":"PH-H4199-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All architectural-engineering designs and services under this Act, after the usual government procedures for public biddings, shall be awarded to citizens of the Philippines as authorized by existing laws, within one year after approval of this Act. All construction contracts under this Act, after the usual government procedures for public biddings, shall be awarded to citizens of the Philippines or to corporations or associations as authorized by existing laws to engage in construction-business operations in the Philippines."}},{"id":"PH-H4199-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the event the Government may not have the necessary funds to be certified as available for any single contract out of the appropriation herein provided, authority is hereby granted to the contractor to finance from his own funds any single contract for any of said structures, and the appropriations authorized under Section one hereof shall be made available for the amortization of both principal and interest of any unpaid balance at a rate of interest not exceeding twelve per cent per annum; Provided, That no contract shall be amortized and paid for a period longer than twenty years."}},{"id":"PH-H4199-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Notwithstanding any law, rule or regulation to the contrary, the contracts herein to be entered into are authorized to be discountable in any local bank and/or financing institution doing business in the Philippines in amounts not exceeding eighty-five per cent of the contract, provided such discounting shall have the prior favorable endorsement of the President of the Philippines."}},{"id":"PH-H4199-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Upon approval of the President of the Philippines of the projects to be implemented, the Secretary of Public Works and Communications shall forthwith cause to be published once every week for three consecutive weeks in at least two newspapers of general circulation, a notice inviting all eligible contractors to participate in a public bidding for the projects so approved, subject to the usual government procedures necessary for public biddings."}},{"id":"PH-H4199-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"All prior appropriations for national buildings and other improvement projects pertaining to the Legislative, Judiciary and Executive Groups are hereby made increments of the appropriation provided for in Section one hereof and subject to the other provisions of this Act."}},{"id":"PH-H4199-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"All laws inconsistent herewith are hereby repealed."}},{"id":"PH-H4199-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4200"] = {"id":"PH-H4200","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5399_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将北三宝颜省辛丹岸市镇迪诺科特村的名称变更为Ricardo G. Macias村的法案","en":"An Act Changing the Name of Barrio Dinokot in the Municipality of Sindangan, Province of Zamboanga del Norte, to Barrio Ricardo G. Macias","orig":"An Act Changing the Name of Barrio Dinokot in the Municipality of Sindangan, Province of Zamboanga del Norte, to Barrio Ricardo G. Macias"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5399","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5399_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4200-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio Dinokot in the Municipality of Sindangan, Province of Zamboanga del Norte, is hereby changed to Barrio Ricardo G. Macias."}},{"id":"PH-H4200-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Barrio Dinokot in the Municipality of Sindangan, Province of Zamboanga del Norte, to Barrio Ricardo G. Macias","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4201"] = {"id":"PH-H4201","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5400_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Salug市","en":"An Act Creating Barrio Tapalan in the Municipality of Salug, Province of Zamboanga del Norte","orig":"An Act Creating Barrio Tapalan in the Municipality of Salug, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5400","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5400_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4201-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Tapalan in Barrio Palandoc, Municipality of Salug, Province of Zamboanga del Norte, is separated from said barrio and converted into a distinct and independent barrio of said municipality, to be known as Barrio Tapalan. The said barrio shall be bounded as follows:\n1. North-Starting from the Northeastern corner of Lot No. 2711, going counterclockwise, proceed to Lot No. 2716, 2725, 2726, 2728 and 2729;\n2. East-Take all areas traversed by Palandoc River;\n3. South-By Pls-742;\n4. West-Take all areas traversed by Lipakan River.\nAll areas within bounds of delineation comprise the proposed Barrio Tapalan."}},{"id":"PH-H4201-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
  FT["PH-H4202"] = {"id":"PH-H4202","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5401_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Salug市","en":"An Act Creating a Barrio Rambon in the Municipality of Salug, Province of Zamboanga del Norte","orig":"An Act Creating a Barrio Rambon in the Municipality of Salug, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5401","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5401_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4202-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Rambon in the Municipality of Salug, Province of Zamboanga del Norte, is hereby converted into a distinct and independent barrio of said municipality, to be known as Barrio Rambon. Said barrio shall be bounded as follows:\n1. North-Salug River;\n2. East-Matingon Creek;\n3. South-Starting from corner of Lot 3391, 3392, 3393, 3398 and 3447, thence draw a straight line due East until it reaches Matingon Creek;\n4. West-Guisapong Creek.\nAll areas within bounds of delineation comprise the proposed barrio of Rambon."}},{"id":"PH-H4202-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p59"};
